var STORAGE_KEY="uruspot_favoritos";var favoritosCache=null;export function leerFavoritos(onError){if(favoritosCache!==null)return favoritosCache;try{favoritosCache=JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")}catch(e){if(onError)onError(e,"leerFavoritos");favoritosCache={}}return favoritosCache}export function guardarFavoritos(f,onError){favoritosCache=f;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(f))}catch(e){if(onError)onError(e,"guardarFavoritos")}}export function invalidarCacheFavoritos(){favoritosCache=null}